async function snMeasureMemoryFootprint(doc = document, options = {}) {
  const started=performance.now(),queue=options.heapOnly?[]:[doc],resources=new Map();
  const result={roots:0,nodes:0,styles:0,actionCssChars:0,themeCssChars:0,otherCssChars:0,partial:Boolean(options.heapOnly),domScanDeferred:Boolean(options.heapOnly)};
  while(queue.length){
    let slice=performance.now();
    do {
      const root=queue.pop();result.roots++;
      for(const node of root.querySelectorAll('*')){
        result.nodes++;
        if(node.localName==='link'&&node.hasAttribute('data-sn-ai-shared-style'))resources.set(node.href,Number(node.dataset.snAiCssChars)||0);
        if(node.shadowRoot)queue.push(node.shadowRoot);
        if(node.localName==='style'){
          result.styles++;
          // Read text-node lengths, never concatenate megabytes of CSS.
          let length=0;for(const text of node.childNodes)if(text.nodeType===3)length+=text.length;
          const key=node.hasAttribute('data-sn-ai-action-style')?'actionCssChars':node.hasAttribute('data-sn-ai-space-theme')?'themeCssChars':'otherCssChars';
          result[key]+=length;
        }
        // A single root may contain thousands of nodes. Bound that pass too,
        // not just the gaps between shadow roots.
        if(result.nodes%32===0&&performance.now()-slice>=4){
          await new Promise(resolve=>setTimeout(resolve,0));slice=performance.now();
        }
        if(result.nodes>100000||performance.now()-started>1000){result.partial=true;queue.length=0;break;}
      }
      if(result.nodes>100000||result.roots>5000||performance.now()-started>1000){result.partial=true;queue.length=0;break;}
    }while(queue.length&&performance.now()-slice<4);
    if(queue.length)await new Promise(resolve=>setTimeout(resolve,0));
  }
  const memory=performance.memory;
  result.sharedCssResourceCount=resources.size;
  result.sharedCssSourceChars=[...resources.values()].reduce((sum,length)=>sum+length,0);
  result.heapUsedBytes=Number.isFinite(memory?.usedJSHeapSize)?memory.usedJSHeapSize:null;
  result.heapAllocatedBytes=Number.isFinite(memory?.totalJSHeapSize)?memory.totalJSHeapSize:null;
  result.heapLimitBytes=Number.isFinite(memory?.jsHeapSizeLimit)?memory.jsHeapSizeLimit:null;
  result.durationMs=Math.round(performance.now()-started);
  return result;
}
function snGreetingMessageInfo(message) {
  const props=message.getProperties?.()||{},native=props.message?.data?.props?.message||{};
  const excluded='sn-chat-control-chat-summary-card,.chat-summary-content,.chat-summary-footer,[data-typing],.typing-indicator,.now-chat-message-typing,[role="status"]';
  let control=false;
  const visit=root=>{if(!root||control)return;for(const node of root.querySelectorAll('*')){if(node.matches?.(excluded)||/typing|summary/i.test(node.localName||'')){control=true;break;}if(node.shadowRoot)visit(node.shadowRoot);}};
  visit(message.shadowRoot);
  const bubble=message.shadowRoot?.querySelector('.now-chat-message:not(.system)');
  const text=String(native.formatted_message??native.text??bubble?.textContent??'').trim();
  const type=String(native.type||native.message_type||props.message?.type||'');
  const system=Boolean(props.isSystem||native.is_system||control||/typing|summary|system/i.test(type));
  return {right:props.orientation==='right'||Boolean(message.shadowRoot?.querySelector('.now-chat-message.right:not(.system)')),system,text,
    meaningful:!system&&!!text&&!/^(?:\.{3}|…|(?:\S+\s+)?is typing(?:\.{3}|…)?|typing(?:\.{3}|…)?)$/i.test(text),
    orientation:String(props.orientation||''),type:String(native.messageType||type).slice(0,80),
    messageId:String(native.messageId||native.sys_id||'').slice(0,100),timestamp:String(native.timestamp||'').slice(0,60),
    excludedReason:system?(control?'summary-or-typing-control':'system-or-control-message'):!text?'empty-message':/^(?:\.{3}|…|(?:\S+\s+)?is typing(?:\.{3}|…)?|typing(?:\.{3}|…)?)$/i.test(text)?'typing-text':'',
    status:native.delivery_status,key:native.messageId||native.sys_id||message};
}
function snClassifyCustomerGreeting(value) {
  const text=String(value||'').trim(),maxGreetingLength="Good afternoon, I hope you're doing well".length+10;
  const normal=text.normalize('NFKC').replace(/[’‘]/g,"'").toLowerCase();
  // Match whole phrases/words, never substrings such as hi inside shipping.
  const phrases=/\b(?:good\s+(?:morning|afternoon|evening|day)|(?:very\s+)?(?:happy|lovely)\s+(?:morning|afternoon|evening)|morning|afternoon|evening|hello(?:\s+there)?|hiya|heya|howdy|greetings|hey(?:\s+there)?|hi(?:\s+there)?|dear\s+(?:team|support|all)|hope\s+(?:you(?:'re|\s+are)?|all\s+is)\s+(?:doing\s+)?(?:well|good|ok(?:ay)?)|i\s+hope\s+you(?:'re|\s+are)\s+doing\s+well|how\s+are\s+you(?:\s+doing)?|how(?:'s|\s+is)\s+it\s+going)\b/gi;
  const matches=[...normal.matchAll(phrases)];
  const meaningful=normal.replace(/[^\p{L}\p{N}]/gu,'');
  const remainder=normal.replace(phrases,' ').replace(/\bi\b(?=\s*[,!.?]*\s*$)/g,'').replace(/[^\p{L}\p{N}]/gu,'');
  const ratio=meaningful.length?(meaningful.length-remainder.length)/meaningful.length:0;
  const issue=/\b(?:issue|problem|error|fault|broken|stuck|unable|cannot|can't|cant|not\s+(?:working|printing|loading)|help|order|printer|password|access|login|log\s*in|cancel|refund|sap|vpn)\b/i.test(normal);
  let code=null,reason='uncertain-customer-message';
  if(matches.length&&text.length<maxGreetingLength&&ratio>0.7&&!issue&&remainder.length===0){code='w';reason='short-greeting-only';}
  else if((1-ratio)>0.5&&(issue||remainder.length>=12)){code='q';reason='predominantly-non-greeting';}
  return {code,reason,greetingRatio:Math.round(ratio*1000)/1000,nonGreetingRatio:Math.round((1-ratio)*1000)/1000,messageLength:text.length,maxGreetingLength,issueMarker:issue,matchedGreetings:matches.slice(0,8).map(match=>match[0]),unmatchedChars:remainder.length};
}
function snGreetingDecisionEvidence(messages) {
  const infos=messages.map(snGreetingMessageInfo),selectedIndex=infos.findLastIndex(info=>info.meaningful);
  const snapshot=(info,index,limit)=>({index,messageId:info.messageId,timestamp:info.timestamp,type:info.type,orientation:info.orientation,right:info.right,system:info.system,meaningful:info.meaningful,excludedReason:info.excludedReason,text:info.text.slice(0,limit),textLength:info.text.length,truncated:info.text.length>limit});
  const selected=selectedIndex>=0?infos[selectedIndex]:null;
  const classification=selected&&!selected.right?snClassifyCustomerGreeting(selected.text):null;
  return {code:classification?classification.code:'w',reason:classification?classification.reason:!selected?'no-meaningful-message':'last-meaningful-message-is-agent',classification,messageCount:infos.length,excludedCount:infos.filter(info=>!info.meaningful).length,
    selected:selected?snapshot(selected,selectedIndex,1800):null,recent:infos.slice(-6).map((info,index)=>snapshot(info,Math.max(0,infos.length-6)+index,400))};
}
function snWorkspaceTabBars(){
  const bars=[];const walk=root=>{for(const el of root.querySelectorAll('*')){if(el.localName==='sn-workspace-tab-bar'){const props=el.getProperties?.();if(Array.isArray(props?.tabList))bars.push({el,props});}if(el.shadowRoot)walk(el.shadowRoot);}};walk(document);return bars;
}
function snWorkspacePrimary(){return snWorkspaceTabBars().find(bar=>bar.props.type==='primary')||null;}
function snWorkspaceFocusIMS(number){
  const bar=snWorkspacePrimary(),tab=bar?.props.tabList.find(tab=>tab.table==='interaction'&&String(tab.title||tab.formHeaderInfo?.recordDisplayValue||'').toUpperCase()===String(number).toUpperCase());
  if(!tab||typeof bar.props.onClickTab!=='function')return false;bar.props.onClickTab(tab.tab_id);return true;
}
function snWorkspaceFocusSubtab(parentId,tabId){
  const main=snWorkspacePrimary(),parent=main?.props.tabList.find(t=>String(t.tab_id)===String(parentId));
  if(!parent?.tabList?.some(t=>String(t.tab_id)===String(tabId)))return false;
  const bar=snWorkspaceTabBars().find(b=>b.props.type!=='primary'&&b.props.tabList.some(t=>String(t.tab_id)===String(tabId)&&String(t.parentTabId)===String(parentId)));
  if(!bar||typeof bar.props.onClickTab!=='function')return false;bar.props.onClickTab(tabId);return true;
}
function snIncomingOfferText(button){
  let card=button;while(card&&card.localName!=='sn-inbox-card')card=card.parentElement||card.getRootNode?.().host;
  const parts=[];const collect=root=>{if(!root||parts.length>=80)return;if(root.shadowRoot)collect(root.shadowRoot);for(const node of root.childNodes||[]){if(parts.length>=80)break;if(node.nodeType===3){const text=String(node.textContent||'').trim();if(text)parts.push(text.slice(0,300));}else if(node.nodeType===1&&!/^(STYLE|SCRIPT)$/.test(node.tagName))collect(node);}};
  collect(card);return parts.join(' ').slice(0,2400);
}
